//! cobra v1.10.2 hidden `__complete` / `__completeNoDesc` command (`completions.go`): computes the completion
//! choices of a partial command line for the shell scripts generated by `qovery completion <shell>`.

use crate::pflag::{FlagSet, parse_go_bool};
use qovery_cobra::{Command, Ctx, Flag, FlagKind, NodeId, Tree};
use std::io::Write;

pub const SHELL_COMP_REQUEST_CMD: &str = "__complete";
pub const SHELL_COMP_NO_DESC_REQUEST_CMD: &str = "__completeNoDesc";

pub const DIRECTIVE_DEFAULT: i64 = 0;
pub const DIRECTIVE_ERROR: i64 = 1;
pub const DIRECTIVE_NO_SPACE: i64 = 2;
pub const DIRECTIVE_NO_FILE_COMP: i64 = 4;
pub const DIRECTIVE_FILTER_FILE_EXT: i64 = 8;
pub const DIRECTIVE_FILTER_DIRS: i64 = 16;
pub const DIRECTIVE_KEEP_ORDER: i64 = 32;
const DIRECTIVE_MAX_VALUE: i64 = 64;

pub const ACTIVE_HELP_MARKER: &str = "_activeHelp_ ";
const CONFIG_ENV_VAR_GLOBAL_PREFIX: &str = "COBRA";
const CONFIG_ENV_VAR_SUFFIX_DESCRIPTIONS: &str = "COMPLETION_DESCRIPTIONS";

/// cobra `initCompleteCmd`'s command.
pub fn command() -> Command {
    Command::new(&format!("{SHELL_COMP_REQUEST_CMD} [command-line]"))
        .alias(SHELL_COMP_NO_DESC_REQUEST_CMD)
        .hidden()
        .disable_flag_parsing()
        .args(qovery_cobra::ArgsRule::Minimum(1))
        .short("Request shell completion choices for the specified command-line")
        .long(&format!(
            "{SHELL_COMP_REQUEST_CMD} is a special command that is used by the shell completion logic\n{}",
            "to request completion choices for the specified command-line."
        ))
        .disable_flags_in_use_line()
        .run(run)
}

/// Name of the root-level command `args` resolve to among `names` (cobra `Find` restricted to the root level),
/// with the root's flags (`--verbose`, `--help`) used to skip flag values like cobra's `stripFlags`.
fn resolves_to(args: &[String], name: &str, aliases: &[&str]) -> bool {
    let mut child = Command::new(name).run(|_| {});
    for a in aliases {
        child = child.alias(a);
    }
    let root = Command::new("qovery")
        .flag(Flag::bool("verbose", "Verbose output").persistent())
        .subcommand(child);
    let tree = Tree::build(root);
    let (id, _, err) = tree.find(args);
    err.is_none() && id != 0
}

/// cobra only adds `__complete` to the root when it is the command being called
/// (`subCmd, _, err := c.Find(args); if err != nil || subCmd.Name() != ShellCompRequestCmd { remove }`).
pub fn is_called(args: &[String]) -> bool {
    resolves_to(
        args,
        SHELL_COMP_REQUEST_CMD,
        &[SHELL_COMP_NO_DESC_REQUEST_CMD],
    )
}

/// cobra `cmd.CalledAs() == ShellCompNoDescRequestCmd`.
fn called_as_no_desc() -> bool {
    let args: Vec<String> = std::env::args().skip(1).collect();
    resolves_to(&args, SHELL_COMP_NO_DESC_REQUEST_CMD, &[])
}

/// cobra `configEnvVar`: `<NAME>_<SUFFIX>` upper-cased, non `[A-Z0-9_]` characters replaced by `_`.
pub fn config_env_var(name: &str, suffix: &str) -> String {
    format!("{name}_{suffix}")
        .to_uppercase()
        .chars()
        .map(|c| {
            if c.is_ascii_uppercase() || c.is_ascii_digit() || c == '_' {
                c
            } else {
                '_'
            }
        })
        .collect()
}

/// cobra `getEnvConfig`.
fn get_env_config(root_name: &str, suffix: &str) -> String {
    let v = std::env::var(config_env_var(root_name, suffix)).unwrap_or_default();
    if v.is_empty() {
        std::env::var(config_env_var(CONFIG_ENV_VAR_GLOBAL_PREFIX, suffix)).unwrap_or_default()
    } else {
        v
    }
}

/// cobra `GetActiveHelpConfig`.
fn active_help_config(root_name: &str) -> String {
    let global = std::env::var(config_env_var(CONFIG_ENV_VAR_GLOBAL_PREFIX, "ACTIVE_HELP"))
        .unwrap_or_default();
    if global != "0" {
        std::env::var(config_env_var(root_name, "ACTIVE_HELP")).unwrap_or_default()
    } else {
        global
    }
}

/// cobra `ShellCompDirective.string()`.
pub fn directive_string(d: i64) -> String {
    let mut directives = Vec::new();
    let names = [
        (DIRECTIVE_ERROR, "ShellCompDirectiveError"),
        (DIRECTIVE_NO_SPACE, "ShellCompDirectiveNoSpace"),
        (DIRECTIVE_NO_FILE_COMP, "ShellCompDirectiveNoFileComp"),
        (DIRECTIVE_FILTER_FILE_EXT, "ShellCompDirectiveFilterFileExt"),
        (DIRECTIVE_FILTER_DIRS, "ShellCompDirectiveFilterDirs"),
        (DIRECTIVE_KEEP_ORDER, "ShellCompDirectiveKeepOrder"),
    ];
    for (bit, name) in names {
        if d & bit != 0 {
            directives.push(name);
        }
    }
    if directives.is_empty() {
        directives.push("ShellCompDirectiveDefault");
    }
    if d >= DIRECTIVE_MAX_VALUE {
        return format!("ERROR: unexpected ShellCompDirective value: {d}");
    }
    directives.join(", ")
}

/// cobra `CompDebug`.
fn comp_debug(msg: &str, print_to_stderr: bool) {
    let msg = format!("[Debug] {msg}");
    if let Ok(path) = std::env::var("BASH_COMP_DEBUG_FILE")
        && !path.is_empty()
        && let Ok(mut f) = std::fs::OpenOptions::new()
            .append(true)
            .create(true)
            .open(&path)
    {
        let _ = f.write_all(msg.as_bytes());
    }
    if print_to_stderr {
        eprint!("{msg}");
    }
}

/// cobra `CompErrorln`.
fn comp_errorln(msg: &str) {
    comp_debug(&format!("[Error] {msg}\n"), true);
}

/// Go `%v` of a `[]string`.
fn go_slice(v: &[String]) -> String {
    format!("[{}]", v.join(" "))
}

/// The `Run` of cobra's `__complete` command.
fn run(ctx: &Ctx) {
    let tree = ctx.tree();
    let root_name = tree.root().name().to_string();
    let (_final_id, completions, directive, err) = get_completions(tree, ctx.args());
    if let Some(e) = err {
        comp_errorln(&e);
    }

    let mut no_descriptions = called_as_no_desc();
    if !no_descriptions
        && let Some(b) = parse_go_bool(&get_env_config(
            &root_name,
            CONFIG_ENV_VAR_SUFFIX_DESCRIPTIONS,
        ))
    {
        no_descriptions = !b;
    }
    let no_active_help = active_help_config(&root_name) == "0";
    let mut out = std::io::stdout().lock();
    for comp in completions {
        if no_active_help && comp.starts_with(ACTIVE_HELP_MARKER) {
            continue;
        }
        let mut comp = comp.as_str();
        if no_descriptions {
            comp = comp.split('\t').next().unwrap_or("");
        }
        comp = comp.split('\n').next().unwrap_or("");
        let _ = writeln!(out, "{}", comp.trim());
    }
    let _ = writeln!(out, ":{directive}");
    let _ = out.flush();
    eprintln!(
        "Completion ended with directive: {}",
        directive_string(directive)
    );
}

/// cobra `isFlagArg`.
fn is_flag_arg(arg: &str) -> bool {
    let b = arg.as_bytes();
    (b.len() >= 3 && &b[0..2] == b"--") || (b.len() >= 2 && b[0] == b'-' && b[1] != b'-')
}

fn bytes_str(b: &[u8]) -> String {
    String::from_utf8_lossy(b).into_owned()
}

/// cobra `findFlag` (on the merged flags of the command).
fn find_flag(tree: &Tree, id: NodeId, name: &str) -> Option<Flag> {
    let all = tree.all_flags(id);
    let mut name = name.to_string();
    if name.len() == 1 {
        let c = name.chars().next().unwrap();
        let local = tree.local_flags(id);
        let inherited = tree.inherited_flags(id);
        name = local
            .iter()
            .chain(inherited.iter())
            .find(|f| f.shorthand == Some(c))?
            .name
            .clone();
    }
    all.into_iter().find(|f| f.name == name)
}

struct FlagCheck {
    flag: Option<Flag>,
    args: Vec<String>,
    to_complete: String,
    /// `flagCompError`
    err: Option<String>,
}

/// cobra `checkIfFlagCompletion`.
fn check_if_flag_completion(
    tree: &Tree,
    id: NodeId,
    args: Vec<String>,
    last_arg: String,
) -> FlagCheck {
    if tree.node(id).disable_flag_parsing {
        return FlagCheck {
            flag: None,
            args,
            to_complete: last_arg,
            err: None,
        };
    }
    let mut flag_name = String::new();
    let mut trimmed = args.clone();
    let mut flag_with_equal = false;
    let org_last_arg = last_arg.clone();
    let mut last_arg = last_arg;

    if last_arg.starts_with('-') {
        if let Some(index) = last_arg.find('=') {
            let b = last_arg.as_bytes();
            if b[..index].starts_with(b"--") {
                flag_name = bytes_str(&b[2..index]);
            } else {
                flag_name = bytes_str(&b[index - 1..index]);
            }
            last_arg = last_arg[index + 1..].to_string();
            flag_with_equal = true;
        } else {
            return FlagCheck {
                flag: None,
                args,
                to_complete: last_arg,
                err: None,
            };
        }
    }

    if flag_name.is_empty()
        && let Some(prev) = args.last()
        && is_flag_arg(prev)
        && !prev.contains('=')
    {
        let b = prev.as_bytes();
        flag_name = if prev.starts_with("--") {
            bytes_str(&b[2..])
        } else {
            bytes_str(&b[b.len() - 1..])
        };
        trimmed = args[..args.len() - 1].to_vec();
    }

    if flag_name.is_empty() {
        return FlagCheck {
            flag: None,
            args: trimmed,
            to_complete: last_arg,
            err: None,
        };
    }

    let Some(flag) = find_flag(tree, id, &flag_name) else {
        return FlagCheck {
            flag: None,
            args,
            to_complete: org_last_arg,
            err: Some(format!(
                "Subcommand '{}' does not support flag '{}'",
                tree.node(id).name(),
                flag_name
            )),
        };
    };
    if !flag_with_equal && flag.kind == FlagKind::Bool {
        // a boolean flag takes no value: not a flag value completion
        return FlagCheck {
            flag: None,
            args,
            to_complete: last_arg,
            err: None,
        };
    }
    FlagCheck {
        flag: Some(flag),
        args: trimmed,
        to_complete: last_arg,
        err: None,
    }
}

/// cobra `getFlagNameCompletions`.
fn flag_name_completions(flag: &Flag, to_complete: &str) -> Vec<String> {
    if flag.hidden || !flag.deprecated.is_empty() {
        return Vec::new();
    }
    let mut out = Vec::new();
    let long = format!("--{}", flag.name);
    if long.starts_with(to_complete) {
        out.push(format!("{long}\t{}", flag.usage));
    }
    if let Some(c) = flag.shorthand {
        let short = format!("-{c}");
        if short.starts_with(to_complete) {
            out.push(format!("{short}\t{}", flag.usage));
        }
    }
    out
}

/// Inherited flags then non-inherited flags, each sorted (cobra `InheritedFlags().VisitAll` +
/// `NonInheritedFlags().VisitAll`).
fn visit_order(tree: &Tree, id: NodeId) -> Vec<Flag> {
    let mut v = tree.inherited_flags(id);
    v.extend(tree.local_flags(id));
    v
}

/// cobra `completeRequireFlags`.
fn complete_require_flags(tree: &Tree, id: NodeId, fs: &FlagSet, to_complete: &str) -> Vec<String> {
    visit_order(tree, id)
        .iter()
        .filter(|f| f.required && !fs.changed.contains(&f.name))
        .flat_map(|f| flag_name_completions(f, to_complete))
        .collect()
}

/// Commands declared with `ValidArgsFunction: NoFileCompletions`: cobra's `completion` command and its children.
fn has_no_file_completions(tree: &Tree, id: NodeId) -> bool {
    let is_completion_cmd = |id: NodeId| {
        let n = tree.node(id);
        n.parent == Some(0) && n.name() == crate::COMPLETION_CMD_NAME
    };
    is_completion_cmd(id) || tree.node(id).parent.is_some_and(is_completion_cmd)
}

/// `ValidArgsFunction` of cobra's default `help` command: the sub-commands of the command named by `args`.
fn help_valid_args(tree: &Tree, args: &[String], to_complete: &str) -> (Vec<String>, i64) {
    let (cmd, _, err) = tree.find(args);
    if err.is_some() {
        return (Vec::new(), DIRECTIVE_NO_FILE_COMP);
    }
    let is_root = tree.node(cmd).parent.is_none();
    let completions = tree
        .sorted_children(cmd)
        .into_iter()
        .filter(|sub| tree.is_available_command(sub.id) || (sub.is_help_command && is_root))
        .filter(|sub| sub.name().starts_with(to_complete))
        .map(|sub| format!("{}\t{}", sub.name(), sub.short))
        .collect();
    (completions, DIRECTIVE_NO_FILE_COMP)
}

/// cobra `Command.getCompletions`: `(finalCmd, completions, directive, error)`.
pub fn get_completions(
    tree: &Tree,
    args: &[String],
) -> (Option<NodeId>, Vec<String>, i64, Option<String>) {
    let Some((to_complete, trimmed_args)) = args.split_last() else {
        return (None, Vec::new(), DIRECTIVE_DEFAULT, None);
    };
    let (final_id, final_args, err) = tree.find(trimmed_args);
    if err.is_some() {
        return (
            None,
            Vec::new(),
            DIRECTIVE_DEFAULT,
            Some(format!(
                "unable to find a command for arguments: {}",
                go_slice(trimmed_args)
            )),
        );
    }
    let node = tree.node(final_id);
    let disable_flag_parsing = node.disable_flag_parsing;

    let check = check_if_flag_completion(tree, final_id, final_args, to_complete.clone());
    let flag = check.flag;
    let mut final_args = check.args;
    let to_complete = check.to_complete;

    let all_flags = tree.all_flags(final_id);
    let mut fs = FlagSet::new(&all_flags);
    let mut flag_completion = true;
    if !disable_flag_parsing {
        // cobra `ParseFlags`: warnings written by pflag (deprecations) are printed when there is no error
        let parse_flags = |fs: &mut FlagSet, args: &[String]| -> Result<(), String> {
            let before = fs.output.len();
            fs.parse(args)?;
            if fs.output.len() > before {
                eprint!("{}", fs.output);
            }
            Ok(())
        };
        let mut with_dash = final_args.clone();
        with_dash.push("--".to_string());
        let _ = parse_flags(&mut fs, &with_dash);
        let new_arg_count = fs.args.len();
        if let Err(e) = parse_flags(&mut fs, &final_args) {
            return (
                Some(final_id),
                Vec::new(),
                DIRECTIVE_DEFAULT,
                Some(format!(
                    "Error while parsing flags from args {}: {}",
                    go_slice(&final_args),
                    e
                )),
            );
        }
        let real_arg_count = fs.args.len();
        if new_arg_count > real_arg_count {
            flag_completion = false;
        }
    }
    if let Some(e) = check.err
        && flag_completion
    {
        return (Some(final_id), Vec::new(), DIRECTIVE_DEFAULT, Some(e));
    }

    // --help present: no further completions
    if fs.changed.contains("help") {
        return (Some(final_id), Vec::new(), DIRECTIVE_NO_FILE_COMP, None);
    }

    if !disable_flag_parsing {
        final_args = fs.args.clone();
    }

    let mut completions: Vec<String> = Vec::new();
    let mut directive;

    if flag.is_none()
        && to_complete.starts_with('-')
        && !to_complete.contains('=')
        && flag_completion
    {
        completions = complete_require_flags(tree, final_id, &fs, &to_complete);
        if completions.is_empty() {
            for f in visit_order(tree, final_id) {
                let accepts_multiple = matches!(
                    f.kind,
                    FlagKind::StringSlice | FlagKind::StringArray | FlagKind::StringToString
                );
                if !fs.changed.contains(&f.name) || accepts_multiple {
                    completions.extend(flag_name_completions(&f, &to_complete));
                }
            }
        }
        directive = DIRECTIVE_NO_FILE_COMP;
        if completions.len() == 1 && completions[0].ends_with('=') {
            directive = DIRECTIVE_NO_SPACE;
        }
        if !disable_flag_parsing {
            return (Some(final_id), completions, directive, None);
        }
    } else {
        directive = DIRECTIVE_DEFAULT;
        if flag.is_none() {
            let found_local_non_persistent_flag = node
                .flags
                .iter()
                .any(|f| !f.persistent && fs.changed.contains(&f.name));
            if final_args.is_empty() && !found_local_non_persistent_flag {
                for sub in tree.sorted_children(final_id) {
                    let is_help_command = sub.is_help_command && node.parent.is_none();
                    if tree.is_available_command(sub.id) || is_help_command {
                        if sub.name().starts_with(to_complete.as_str()) {
                            completions.push(format!("{}\t{}", sub.name(), sub.short));
                        }
                        directive = DIRECTIVE_NO_FILE_COMP;
                    }
                }
            }
            completions.extend(complete_require_flags(tree, final_id, &fs, &to_complete));
        }
    }

    // no flag completion function is registered in the CLI; the only `ValidArgsFunction`s are cobra's ones:
    // the `help` command's and `NoFileCompletions` on the completion commands
    if !(flag.is_some() && flag_completion) {
        if node.is_help_command {
            let (comps, d) = help_valid_args(tree, &final_args, &to_complete);
            completions.extend(comps);
            directive = d;
        } else if has_no_file_completions(tree, final_id) {
            directive = DIRECTIVE_NO_FILE_COMP;
        }
    }

    (Some(final_id), completions, directive, None)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn a(v: &[&str]) -> Vec<String> {
        v.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn called_detection() {
        assert!(is_called(&a(&["__complete", "app", ""])));
        assert!(is_called(&a(&["--verbose", "__completeNoDesc", ""])));
        assert!(!is_called(&a(&["application", "__complete"])));
        assert!(!is_called(&a(&[])));
        assert!(!is_called(&a(&["help", "__complete"])));
    }

    #[test]
    fn env_var_names() {
        assert_eq!(
            config_env_var("qovery", "ACTIVE_HELP"),
            "QOVERY_ACTIVE_HELP"
        );
        assert_eq!(config_env_var("my-cli.x", "A"), "MY_CLI_X_A");
    }

    #[test]
    fn directives() {
        assert_eq!(directive_string(0), "ShellCompDirectiveDefault");
        assert_eq!(
            directive_string(6),
            "ShellCompDirectiveNoSpace, ShellCompDirectiveNoFileComp"
        );
    }
}
